package com.anonyser.pvpprofittracker;

import static org.junit.Assert.assertEquals;

import org.junit.Test;

/**
 * Bounty Hunter activation fees — what the killer takes off you when you die holding activated
 * ancient warrior gear, so a wrong number here is millions of gp of wrong risk.
 */
public class BhActivationFeeTest
{
	@Test
	public void weaponFeesMatchTheirItemPages()
	{
		// All six cost 50M until the 29 Jan 2025 rebalance, which cut five and left the longsword.
		assertEquals(50_000_000, PvpProfitTrackerPlugin.bhActivationFee(27904)); // Vesta's longsword
		assertEquals(10_000_000, PvpProfitTrackerPlugin.bhActivationFee(27908)); // Statius's warhammer
		assertEquals(10_000_000, PvpProfitTrackerPlugin.bhActivationFee(27916)); // Morrigan's javelin
		assertEquals(5_000_000, PvpProfitTrackerPlugin.bhActivationFee(27900));  // Vesta's spear
		assertEquals(5_000_000, PvpProfitTrackerPlugin.bhActivationFee(27912));  // Morrigan's axe
		assertEquals(5_000_000, PvpProfitTrackerPlugin.bhActivationFee(27920));  // Zuriel's staff
	}

	@Test
	public void bothArmourTiersAreComplete()
	{
		for (int id = 27831; id <= 27841; id++)
		{
			assertEquals("regular armour " + id, 5_000_000, PvpProfitTrackerPlugin.bhActivationFee(id));
		}
		for (int id = 27842; id <= 27852; id++)
		{
			assertEquals("corrupted armour " + id, 1_500_000, PvpProfitTrackerPlugin.bhActivationFee(id));
		}
	}

	@Test
	public void inactiveFormsHoldNoCoins()
	{
		for (final int id : new int[]{27902, 27906, 27910, 27914, 27918, 27922})
		{
			assertEquals("inactive " + id, 0, PvpProfitTrackerPlugin.bhActivationFee(id));
		}
	}
}

package com.anonyser.pvpprofittracker;

import ch.qos.logback.classic.Level;
import ch.qos.logback.classic.Logger;
import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;
import org.slf4j.LoggerFactory;

public class PvpProfitTrackerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		// Dev runs only: surface the plugin's log.debug listener lines. Which slf4j backend
		// answers depends on the test classpath — RuneLite's logback or the slf4j-simple test
		// dependency — so cover both; a hard logback cast here killed the dev client outright
		// when simple won the binding. Under simple, everything lands in ~/.runelite/pvp-dev.log
		// (properties must be set before the first logger is created). Under logback, the
		// properties are inert and the lines go to client.log as usual.
		System.setProperty("org.slf4j.simpleLogger.log.com.anonyser", "debug");
		System.setProperty("org.slf4j.simpleLogger.logFile",
			System.getProperty("user.home") + "/.runelite/pvp-dev.log");
		final org.slf4j.Logger logger = LoggerFactory.getLogger("com.anonyser");
		if (logger instanceof Logger)
		{
			((Logger) logger).setLevel(Level.DEBUG);
		}
		ExternalPluginManager.loadBuiltin(PvpProfitTrackerPlugin.class);
		RuneLite.main(args);
	}
}

package com.anonyser.pvpprofittracker;

import com.google.gson.Gson;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class FightHistoryTest
{
	@Test
	public void relativeShowsTheTwoLargestUnits()
	{
		final long now = 1_000_000_000_000L;
		assertEquals("just now", FightHistory.relative(now, now));
		assertEquals("just now", FightHistory.relative(now, now - 59_000));
		assertEquals("1 minute ago", FightHistory.relative(now, now - 60_000));
		assertEquals("12 minutes ago", FightHistory.relative(now, now - 12 * 60_000));
		assertEquals("1 hour 30 minutes ago", FightHistory.relative(now, now - 90 * 60_000));
		assertEquals("2 hours ago", FightHistory.relative(now, now - 2 * 3_600_000));
		assertEquals("1 day ago", FightHistory.relative(now, now - 24 * 3_600_000L));
		assertEquals("3 days 2 hours ago",
			FightHistory.relative(now, now - (3 * 24 + 2) * 3_600_000L));
		// A clock that went backwards must never render a negative age.
		assertEquals("just now", FightHistory.relative(now, now + 5_000));
	}

	@Test
	public void exactUsesTheFullWeekdayDateAndTime()
	{
		// 2026-07-12 15:45 UTC is a Sunday.
		final long ts = ZonedDateTime.of(2026, 7, 12, 15, 45, 0, 0, ZoneOffset.UTC)
			.toInstant().toEpochMilli();
		assertEquals("Sunday, 12 July 2026 at 3:45 PM", FightHistory.exact(ts, ZoneOffset.UTC));
	}

	@Test
	public void combatLevelMatchesTheGameFormula()
	{
		// Maxed combat stats: 0.25 × (99 + 99 + 49) + 0.325 × (99 + 99) = 126.1
		assertEquals(126.1, FightHistory.combatLevel(99, 99, 99, 99, 99, 99, 99), 1e-9);
		// A fresh level-3: 0.25 × (1 + 10 + 0) + 0.325 × (1 + 1) = 3.4
		assertEquals(3.4, FightHistory.combatLevel(1, 1, 1, 1, 1, 10, 1), 1e-9);
		// Unknown until every stat has answered.
		assertEquals(-1, FightHistory.combatLevel(99, 99, 99, 99, 99, 99, 0), 1e-9);
	}

	@Test
	public void historyRoundTripsThroughJson()
	{
		final Gson gson = new Gson();
		final List<FightHistory.Fight> fights = new ArrayList<>();
		FightHistory.append(fights, new FightHistory.Fight("Some Guy", 126, true, true, true, 123L));
		FightHistory.append(fights, new FightHistory.Fight("Other", 90, false, false, false, 456L));
		final List<FightHistory.Fight> back =
			FightHistory.parse(gson, FightHistory.serialize(gson, fights));
		assertEquals(2, back.size());
		assertEquals("Some Guy", back.get(0).name);
		assertEquals(126, back.get(0).cmb);
		assertTrue(back.get(0).target);
		assertTrue(back.get(0).bh);
		assertTrue(back.get(0).win);
		assertEquals(123L, back.get(0).ts);
		assertEquals("Other", back.get(1).name);
		assertFalse(back.get(1).win);
	}

	@Test
	public void appendDropsTheOldestPastTheCap()
	{
		final List<FightHistory.Fight> fights = new ArrayList<>();
		for (int i = 0; i < FightHistory.MAX_FIGHTS + 25; i++)
		{
			FightHistory.append(fights, new FightHistory.Fight("N" + i, 3, false, false, true, i));
		}
		assertEquals(FightHistory.MAX_FIGHTS, fights.size());
		// The 25 oldest were dropped, the newest survived.
		assertEquals("N25", fights.get(0).name);
		assertEquals("N" + (FightHistory.MAX_FIGHTS + 24), fights.get(fights.size() - 1).name);
	}

	@Test
	public void malformedStorageParsesToAnEmptyHistory()
	{
		final Gson gson = new Gson();
		assertTrue(FightHistory.parse(gson, null).isEmpty());
		assertTrue(FightHistory.parse(gson, "").isEmpty());
		assertTrue(FightHistory.parse(gson, "not json").isEmpty());
		assertTrue(FightHistory.parse(gson, "{\"a\":1}").isEmpty());
		// A null element or a record missing its name is skipped, not fatal.
		assertEquals(1, FightHistory.parse(gson, "[null, {\"ts\":5}, {\"name\":\"X\"}]").size());
	}
}

package com.anonyser.pvpprofittracker;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class FightRecorderTest
{
	private static FightLog.Entry entry(boolean me, int amount)
	{
		final FightLog.Entry e = new FightLog.Entry();
		e.me = me;
		e.amount = amount;
		e.weapon = 1215;
		e.wname = "Dragon dagger";
		return e;
	}

	@Test
	public void settleStampsTheDefendersHp()
	{
		final FightRecorder r = new FightRecorder();
		r.start("Foe", 1_000L, 100);
		r.onDamage(100, true, 30, 1215, "Dragon dagger", false);
		r.onDamage(100, false, 12, 4151, "Abyssal whip", false);
		r.settle(87, 60, false);
		final FightLog log = r.finish("Win", 2_000L, 110, false);
		assertNotNull(log);
		assertEquals(2, log.hits.size());
		// My hit's defender is them; their hit's defender is me.
		assertEquals(60, log.hits.get(0).hp);
		assertEquals(87, log.hits.get(1).hp);
		assertEquals(10, log.duration);
		assertEquals("Win", log.outcome);
	}

	@Test
	public void unsettledHitsKeepUnknownHp()
	{
		final FightRecorder r = new FightRecorder();
		r.start("Foe", 1_000L, 100);
		r.onDamage(100, true, 30, 1215, "Dragon dagger", true);
		final FightLog log = r.finish("Loss", 2_000L, 105, false);
		assertNotNull(log);
		assertEquals(-1, log.hits.get(0).hp);
		assertTrue(log.hits.get(0).spec);
	}

	@Test
	public void nothingRecordedMeansNoLog()
	{
		final FightRecorder r = new FightRecorder();
		r.start("Foe", 1_000L, 100);
		assertNull(r.finish("Win", 2_000L, 110, false));
		assertFalse(r.isActive());
	}

	@Test
	public void disengageTrips50TicksAfterTheLastHit()
	{
		final FightRecorder r = new FightRecorder();
		r.start("Foe", 1_000L, 100);
		r.onDamage(120, true, 5, -1, null, false);
		assertFalse(r.disengaged(120 + FightRecorder.DISENGAGE_TICKS));
		assertTrue(r.disengaged(121 + FightRecorder.DISENGAGE_TICKS));
	}

	@Test
	public void theirRecoilOnMeAlwaysLabels()
	{
		// I hit 40; their (invisible) ring returns 4 = ceil(10%). Same tick, forward order.
		final List<FightLog.Entry> tick = new ArrayList<>();
		tick.add(entry(true, 40));
		tick.add(entry(false, 4));
		FightRecorder.labelReflections(tick, false);
		assertNull(tick.get(0).tag);
		assertEquals("recoil", tick.get(1).tag);
		assertEquals(-1, tick.get(1).weapon);
	}

	@Test
	public void myRecoilOnThemNeedsTheRingWorn()
	{
		// They hit 47; my ring's 5 displays FIRST (seen live). Reversed-order shape.
		final List<FightLog.Entry> withoutRing = new ArrayList<>();
		withoutRing.add(entry(true, 5));
		withoutRing.add(entry(false, 47));
		FightRecorder.labelReflections(withoutRing, false);
		assertNull(withoutRing.get(0).tag);

		final List<FightLog.Entry> withRing = new ArrayList<>();
		withRing.add(entry(true, 5));
		withRing.add(entry(false, 47));
		FightRecorder.labelReflections(withRing, true);
		assertEquals("recoil", withRing.get(0).tag);
	}

	@Test
	public void vengeanceLabelsWithoutAnyRing()
	{
		// They hit me 20; my Vengeance returns floor(15) on them.
		final List<FightLog.Entry> tick = new ArrayList<>();
		tick.add(entry(false, 20));
		tick.add(entry(true, 15));
		FightRecorder.labelReflections(tick, false);
		assertEquals("venge", tick.get(1).tag);
		assertFalse(tick.get(1).spec);
	}

	@Test
	public void ordinaryExchangesAreNotLabelled()
	{
		// 7 after a 25 shapes as neither recoil (3) nor venge (18), in either order.
		final List<FightLog.Entry> tick = new ArrayList<>();
		tick.add(entry(true, 25));
		tick.add(entry(false, 7));
		FightRecorder.labelReflections(tick, false);
		assertNull(tick.get(0).tag);
		assertNull(tick.get(1).tag);
	}

	@Test
	public void reflectShapesMatchTheLiveTestedMaths()
	{
		assertEquals('R', FightRecorder.reflectShape(40, 4));
		assertEquals('R', FightRecorder.reflectShape(47, 5));
		assertEquals('R', FightRecorder.reflectShape(42, 5));
		assertEquals('V', FightRecorder.reflectShape(20, 15));
		assertEquals('-', FightRecorder.reflectShape(3, 25));
		assertEquals('-', FightRecorder.reflectShape(0, 4));
		assertEquals('-', FightRecorder.reflectShape(40, 0));
	}
}

package com.anonyser.pvpprofittracker;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class FightLogTest
{
	private static FightLog log(String name, long ts)
	{
		final FightLog l = new FightLog();
		l.name = name;
		l.ts = ts;
		l.startTs = ts - 30_000;
		l.duration = 50;
		l.outcome = "Win";
		final FightLog.Entry e = new FightLog.Entry();
		e.t = 3;
		e.me = true;
		e.weapon = 1215;
		e.wname = "Dragon dagger";
		e.amount = 22;
		e.hp = 41;
		l.hits.add(e);
		return l;
	}

	@Test
	public void roundTripsThroughJson()
	{
		final Gson gson = new Gson();
		final List<FightLog> logs = new ArrayList<>();
		logs.add(log("Foe", 1000L));
		final List<FightLog> back = FightLog.parse(gson, FightLog.serialize(gson, logs));
		assertEquals(1, back.size());
		final FightLog l = back.get(0);
		assertEquals("Foe", l.name);
		assertEquals(1000L, l.ts);
		assertEquals("Win", l.outcome);
		assertEquals(1, l.hits.size());
		assertEquals(22, l.hits.get(0).amount);
		assertEquals("Dragon dagger", l.hits.get(0).wname);
		assertEquals(41, l.hits.get(0).hp);
		assertTrue(l.hits.get(0).me);
	}

	@Test
	public void garbageAndEmptyParseToNothing()
	{
		final Gson gson = new Gson();
		assertTrue(FightLog.parse(gson, null).isEmpty());
		assertTrue(FightLog.parse(gson, "").isEmpty());
		assertTrue(FightLog.parse(gson, "not json").isEmpty());
	}

	@Test
	public void appendDropsTheOldestPastTheCap()
	{
		final List<FightLog> logs = new ArrayList<>();
		for (int i = 0; i < FightLog.MAX_LOGS + 5; i++)
		{
			FightLog.append(logs, log("F" + i, i));
		}
		assertEquals(FightLog.MAX_LOGS, logs.size());
		assertEquals(5, logs.get(0).ts);
		assertNull(FightLog.byTs(logs, 4));
		assertNotNull(FightLog.byTs(logs, FightLog.MAX_LOGS + 4));
	}

	@Test
	public void clockFormatsTicksAsMinutesAndSeconds()
	{
		assertEquals("0:00", FightLog.clock(0));
		assertEquals("0:10", FightLog.clock(17));
		assertEquals("1:00", FightLog.clock(100));
		assertEquals("2:06", FightLog.clock(210));
	}
}

package com.anonyser.pvpprofittracker;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/**
 * Matching a hitsplat back to the attack that threw it. No client, no mocks — the queue is fed
 * plain values on purpose.
 */
public class AttackQueueTest
{
	@Test
	public void aBoltInFlightKeepsItsWeaponWhenISpecOnTopOfIt()
	{
		// THE REPORTED BUG. Tick 100: crossbow fired, ~40 cycles of flight, lands on 102.
		// Tick 101: switch to the mace and spec — no projectile, so it stays melee-timed.
		final AttackQueue q = new AttackQueue();
		q.add(AttackQueue.projectile(100, 40, 11959, "Hunters' sunlight crossbow", false));
		q.add(AttackQueue.instantSpec(101, 27857, "Dragon mace (bh)"));
		final AttackQueue.Attack first = q.claim(102);
		final AttackQueue.Attack second = q.claim(102);
		assertEquals("Hunters' sunlight crossbow", first.weaponName);
		assertFalse(first.spec);
		assertEquals("Dragon mace (bh)", second.weaponName);
		assertTrue(second.spec);
	}

	@Test
	public void clawsTagsEverySplatOnItsTickButNotThePassingDart()
	{
		final AttackQueue q = new AttackQueue();
		q.add(AttackQueue.projectile(100, 40, 12926, "Toxic blowpipe", false)); // lands 102
		q.add(AttackQueue.instantSpec(102, 13652, "Dragon claws"));
		final AttackQueue.Attack dart = q.claim(102);
		assertEquals("Toxic blowpipe", dart.weaponName);
		assertFalse(dart.spec);
		for (int i = 0; i < 4; i++)
		{
			final AttackQueue.Attack c = q.claim(102);
			assertEquals("Dragon claws", c.weaponName);
			assertTrue(c.spec);
		}
	}

	@Test
	public void aSpecThatNeverLandsExpiresInsteadOfTaggingTheNextHit()
	{
		// The old bug in miniature: an armed spec flag stealing an unrelated later hit.
		final AttackQueue q = new AttackQueue();
		q.add(AttackQueue.instantSpec(100, 12006, "Enhanced Excalibur"));
		assertNull(q.claim(102));
	}

	@Test
	public void aFizzledShotDoesNotDesyncTheQueue()
	{
		final AttackQueue q = new AttackQueue();
		q.add(AttackQueue.projectile(100, 40, 11959, "Hunters' sunlight crossbow", false));
		q.add(AttackQueue.projectile(104, 40, 861, "Magic shortbow", false));
		assertEquals("Magic shortbow", q.claim(106).weaponName);
	}

	@Test
	public void bothDarkBowArrowsStaySpecOnDifferentTicks()
	{
		final AttackQueue q = new AttackQueue();
		q.add(AttackQueue.projectile(100, 40, 11235, "Dark bow", true)); // lands 102
		q.add(AttackQueue.projectile(100, 70, 11235, "Dark bow", true)); // lands 103
		assertTrue(q.claim(102).spec);
		assertTrue(q.claim(103).spec);
	}

	@Test
	public void aSplatFilteredOutOfTheLogStillConsumesItsAttack()
	{
		// Specced a third party: that splat never reaches the log, but it must still eat the record
		// so the next hit on the real opponent isn't tagged with it.
		final AttackQueue q = new AttackQueue();
		q.add(AttackQueue.instantSpec(100, 1215, "Dragon dagger"));
		assertNotNull(q.claim(100));
		assertNull(q.claim(102));
	}

	@Test
	public void anUnexplainedSplatMatchesNothing()
	{
		// Ordinary melee or a bleed — the plugin falls back to the worn weapon, spec forced false.
		assertNull(new AttackQueue().claim(100));
	}

	@Test
	public void aSpecVarpAfterItsProjectileStillFlagsTheShot()
	{
		final AttackQueue q = new AttackQueue();
		q.add(AttackQueue.projectile(100, 40, 22547, "Voidwaker", false));
		assertTrue(q.markSpec(100));
		assertTrue(q.claim(102).spec);
	}

	@Test
	public void nonsenseFlightIsNotQueued()
	{
		assertNull(AttackQueue.projectile(100, 30 * 60, 861, "Magic shortbow", false));
		assertNull(AttackQueue.projectile(100, -5, 861, "Magic shortbow", false));
	}

	@Test
	public void aProjectileForAQueuedSpecRetimesItInsteadOfDoubling()
	{
		// Voidwaker: the spec energy drop is seen first, then its projectile turns up.
		final AttackQueue q = new AttackQueue();
		final AttackQueue.Attack spec = AttackQueue.instantSpec(100, 22547, "Voidwaker");
		q.add(spec);
		assertNotNull(q.unTimedSpecAt(100));
		assertTrue(q.retime(spec, 40));
		assertNull(q.claim(100));           // no longer lands on its own tick
		assertTrue(q.claim(102).spec);      // it lands when the projectile says it does
	}

	@Test
	public void aReleasedRecordGoesBackToTheRealHit()
	{
		// A recoil splat claims the claws record before the reflection labelling spots it; the
		// genuine claws splat on the same tick must still be able to take it.
		final AttackQueue q = new AttackQueue();
		q.add(AttackQueue.instantSpec(100, 13652, "Dragon claws"));
		final AttackQueue.Attack stolen = q.claim(100);
		assertNotNull(stolen);
		q.release(stolen);
		final AttackQueue.Attack real = q.claim(100);
		assertEquals("Dragon claws", real.weaponName);
		assertTrue(real.spec);
	}

	@Test
	public void theQueueNeverGrowsWithoutBound()
	{
		final AttackQueue q = new AttackQueue();
		for (int i = 0; i < 50; i++)
		{
			q.add(AttackQueue.projectile(100 + i, 40, 861, "Magic shortbow", false));
		}
		assertTrue(q.size() <= AttackQueue.MAX_PENDING);
	}
}

package com.anonyser.pvpprofittracker;

import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class FightDrawMergeTest
{
	private static FightHistory.Fight fight(String name, boolean win, long ts)
	{
		return new FightHistory.Fight(name, 100, false, false, win, ts);
	}

	@Test
	public void winAndLossCollapseIntoOneDrawKeepingTheEarlierTs()
	{
		final List<FightHistory.Fight> fights = new ArrayList<>();
		fights.add(fight("Other", true, 500));
		fights.add(fight("Foe", false, 1_000)); // my death landed first
		fights.add(fight("Foe", true, 3_000));  // theirs three seconds later
		final FightHistory.Fight draw = FightHistory.mergeDoubleDeath(fights, "Foe", 60_000);
		assertNotNull(draw);
		assertTrue(draw.draw);
		assertFalse(draw.win);
		assertEquals(1_000, draw.ts); // the first record's ts — the fight log's key
		assertEquals("Draw", draw.outcomeText());
		assertEquals(2, fights.size()); // the unrelated fight + the draw
		assertEquals("Other", fights.get(0).name);
	}

	@Test
	public void nameMatchIsCaseInsensitiveAndOldDrawsAreNeverReused()
	{
		final List<FightHistory.Fight> fights = new ArrayList<>();
		final FightHistory.Fight old = fight("foe", false, 100);
		old.draw = true;
		fights.add(old);
		fights.add(fight("FOE", true, 1_000));
		fights.add(fight("foe", false, 2_000));
		final FightHistory.Fight draw = FightHistory.mergeDoubleDeath(fights, "Foe", 60_000);
		assertNotNull(draw);
		assertEquals(2, fights.size());
		assertTrue(fights.get(0).draw); // the old draw was left alone
		assertEquals(1_000, draw.ts);
	}

	@Test
	public void noPairMeansNoChange()
	{
		final List<FightHistory.Fight> fights = new ArrayList<>();
		fights.add(fight("Foe", true, 1_000)); // a win with no matching loss
		assertNull(FightHistory.mergeDoubleDeath(fights, "Foe", 60_000));
		assertEquals(1, fights.size());
		assertFalse(fights.get(0).draw);
	}

	@Test
	public void aStalePairOutsideTheWindowIsNotMerged()
	{
		final List<FightHistory.Fight> fights = new ArrayList<>();
		fights.add(fight("Foe", false, 1_000));
		fights.add(fight("Foe", true, 500_000)); // an old loss + a much later win
		assertNull(FightHistory.mergeDoubleDeath(fights, "Foe", 60_000));
		assertEquals(2, fights.size());
	}

	@Test
	public void oldJsonWithoutTheDrawFieldReadsAsWinOrLoss()
	{
		final com.google.gson.Gson gson = new com.google.gson.Gson();
		final List<FightHistory.Fight> back = FightHistory.parse(gson,
			"[{\"name\":\"Foe\",\"cmb\":100,\"target\":false,\"bh\":false,\"win\":true,\"ts\":5}]");
		assertEquals(1, back.size());
		assertFalse(back.get(0).draw);
		assertEquals("Win", back.get(0).outcomeText());
