	@Override
	protected void startUp()
	{
		try
		{
			// A disable/enable while logged in reuses this instance — don't inherit stale state.
			deathLatchTick = -1;
			lastAliveRiskGp = -1;
			prevTickProtect = false;
			prevTickPos = null;
			loadRepairCosts();
			loadSkullIconMap();
			loadKeepPriority();
			loadPriceOverrides();
			loadFightHistory();
			sessionStart = Instant.now();
			overlay = new PvpProfitTrackerOverlay(this, config);
			overlayManager.add(overlay);
			doubleDeathOverlay = new DoubleDeathOverlay(this, config);
			overlayManager.add(doubleDeathOverlay);
			damageOverlay = new FightDamageOverlay(client, this, config);
			overlayManager.add(damageOverlay);
			oppHpOverlay = new OpponentHpOverlay(client, this, config);
			overlayManager.add(oppHpOverlay);
			opponentTracker = new OpponentTracker(client, hiscoreManager, this, this::updateOpponentPanel);
			combatCalc = new CombatCalc(client, itemManager);
			panel = new PvpProfitTrackerPanel(this, config);
			navButton = NavigationButton.builder()
				.tooltip("PvP Profit Tracker")
				.icon(icon())
				.priority(7)
				.panel(panel)
				.build();
			clientToolbar.addNavigation(navButton);

			// If enabled while already logged in, load this profile's saved tallies now
			// (self-guarded). Must run on the client thread: the plugin-list toggle calls
			// startUp on the EDT, and the barrel recompute prices items through the client's
			// item cache, which asserts client-thread.
			clientThread.invoke(this::load);
		}
		catch (Error | RuntimeException e)
		{
			log.error("startUp failed", e);
			throw e;
		}
	}

	@Override
	protected void shutDown()
	{
		try
		{
			save();
			overlayManager.remove(overlay);
			overlayManager.remove(doubleDeathOverlay);
			overlayManager.remove(damageOverlay);
			overlayManager.remove(oppHpOverlay);
			clientToolbar.removeNavigation(navButton);
			if (panel != null)
			{
				panel.shutdown(); // stop its Swing timers, or they'd hold the dead panel alive
			}
			overlay = null;
			doubleDeathOverlay = null;
			damageOverlay = null;
			oppHpOverlay = null;
			pendingDoubleDeathName = null;
			fightRecorder.discard();
			attacks.clear();
			seenProjectiles.clear();
			fightHud = null;
			final FightBreakdownWindow w = breakdownWindow;
			breakdownWindow = null;
			if (w != null)
			{
				SwingUtilities.invokeLater(w::dispose);
			}
			opponentTracker = null;
			combatCalc = null;
			maxHitInfo = null;
			panel = null;
			navButton = null;
			heldLootKeyCount = 0;
			lootKeySynced = false;
			inventorySynced = false;
			lastInventory.clear();
			bhPointsSynced = false;
			bankInterfaceOpen = false;
			bankOpenedThisLogin = false;
			loadedProfileKey = null;
		}
		catch (Error | RuntimeException e)
		{
			log.error("shutDown failed", e);
			throw e;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		if (e.getGameState() == GameState.LOGIN_SCREEN || e.getGameState() == GameState.HOPPING)
		{
			lootKeySynced = false;
			inventorySynced = false;
			bankOpenedThisLogin = false;
			bankInterfaceOpen = false;
			deathKeepCalibrated = true; // stop any pending death-screen read
			lastBhTargetName = null;
			pendingAutoFocusName = null;
			// A hop/logout ends the fight where it stands — keep what was recorded for review
			// (a fight cut off mid-hop is still one worth reading back).
			if (fightRecorder.isActive())
			{
				saveNoResultFight(client.getTickCount());
			}
			fightHud = null;
			lastCandidateName = null;
			lastSpecEnergy = -1;
			specDropTick = -1000;
			// A new world means the old risk snapshot can't be the one a death books.
			deathLatchTick = -1;
			lastAliveRiskGp = -1;
			prevTickProtect = false;
			prevTickPos = null;
		}
		else if (e.getGameState() == GameState.LOGGED_IN)
		{
			// The profile-changed event can fire before the state reaches LOGGED_IN — load from
			// whichever happens last so the tallies always arm (self-guarded against re-loads).
			ticksSinceLogin = 0;
			load();
			pendingUpdateNote = !PLUGIN_VERSION.equals(
				configManager.getConfiguration(PvpProfitTrackerConfig.GROUP, K_ANNOUNCED));
		}
	}

	@Subscribe
