		chatboxPanelManager.openTextInput("Amount looted back from double death vs " + name + ":")
			.value("")
			.addCharValidator(c -> Character.isLetterOrDigit(c) || c == '.' || c == ',' || c == ' ')
			.onDone((Consumer<String>) this::submitRecovered)
			.build();
	}

