/**
 * The player's OWN max hit, live, using the standard OSRS formulas: boosted levels (potions
 * included), active prayers, worn gear, and the selected combat style resolved from the game's
 * own weapon-style data. With the special-attack bar lit, the number switches to the spec's
 * ceiling for the known PvP spec weapons.
 *
 * Own-state only: per the Plugin Hub review of the 1.1.0 submission, everything opponent-facing
 * (hit chance, defensive assumptions, risk estimation) was removed.
 */
class CombatCalc
{
	private static final org.slf4j.Logger log = org.slf4j.LoggerFactory.getLogger(CombatCalc.class);

	/** Damage scales with Strength and melee strength bonus — unique among ranged weapons. */
	private static final int ECLIPSE_ATLATL = 29000;
	private static final int DARK_BOW = 11235;
	private static final int DARK_BOW_BH = 27853;

	/**
	 * Special-attack MAX-HIT modifiers for the common PvP spec weapons, from the wiki's Special
	 * attacks page. Encoding: {damage multiplier, hits, show-as-total}. show-as-total = 1 means
	 * the number is the whole combo's ceiling (claws) rather than a per-hit value. Weapons not
	 * listed show their normal max hit while the spec bar is lit.
	 */
	private static final java.util.Map<Integer, double[]> SPEC_MAX = new java.util.HashMap<>();
	static
	{
		final double[] dds = {1.15, 2, 0};
		SPEC_MAX.put(1215, dds);  // dragon dagger
		SPEC_MAX.put(1231, dds);  // dragon dagger(p)
		SPEC_MAX.put(5680, dds);  // dragon dagger(p+)
		SPEC_MAX.put(5698, dds);  // dragon dagger(p++)
		SPEC_MAX.put(13652, new double[]{2.0, 4, 1});   // dragon claws — combo ceiling
		SPEC_MAX.put(1434, new double[]{1.5, 1, 0});    // dragon mace
		SPEC_MAX.put(21009, new double[]{1.25, 1, 0});  // dragon sword
		final double[] dKnife = {1.0, 2, 0};
		SPEC_MAX.put(22804, dKnife); // dragon knife
		SPEC_MAX.put(22806, dKnife); // dragon knife(p)
		SPEC_MAX.put(22808, dKnife); // dragon knife(p+)
		final double[] gmaul = {1.0, 1, 0};
		SPEC_MAX.put(4153, gmaul);   // granite maul (instant, no modifier)
		SPEC_MAX.put(12848, gmaul);  // granite maul (or)
		SPEC_MAX.put(24225, gmaul);  // ornate maul
		SPEC_MAX.put(11802, new double[]{1.375, 1, 0}); // Armadyl godsword
		SPEC_MAX.put(20368, new double[]{1.375, 1, 0}); // Armadyl godsword (or)
		SPEC_MAX.put(11804, new double[]{1.21, 1, 0});  // Bandos godsword
		SPEC_MAX.put(20370, new double[]{1.21, 1, 0});  // Bandos godsword (or)
		SPEC_MAX.put(27690, new double[]{1.5, 1, 0});   // Voidwaker (guaranteed, up to 150%)
		SPEC_MAX.put(DARK_BOW, new double[]{1.3, 2, 0});    // dark bow (1.5 with dragon arrows)
		SPEC_MAX.put(DARK_BOW_BH, new double[]{1.3, 2, 0}); // dark bow (bh)
		SPEC_MAX.put(19481, new double[]{1.25, 1, 0});  // heavy ballista
		SPEC_MAX.put(26712, new double[]{1.25, 1, 0});  // heavy ballista (or)
		SPEC_MAX.put(13576, new double[]{1.5, 1, 0});   // dragon warhammer
		SPEC_MAX.put(26710, new double[]{1.5, 1, 0});   // dragon warhammer (or)
		SPEC_MAX.put(28035, new double[]{1.5, 1, 0});   // corrupted dragon warhammer (bh)
		SPEC_MAX.put(27908, new double[]{1.25, 1, 0});  // Statius's warhammer (bh) — Smash, up to 125% max
		SPEC_MAX.put(21003, new double[]{1.0, 1, 0});   // elder maul (accuracy-only spec)
		SPEC_MAX.put(27100, new double[]{1.0, 1, 0});   // elder maul (or)
		SPEC_MAX.put(27857, new double[]{1.5, 1, 0});   // dragon mace (bh)
		SPEC_MAX.put(1305, new double[]{1.25, 1, 0});   // dragon longsword
		SPEC_MAX.put(27859, new double[]{1.25, 1, 0});  // dragon longsword (bh)
		SPEC_MAX.put(10887, new double[]{1.1, 1, 0});   // barrelchest anchor
		SPEC_MAX.put(27855, new double[]{1.25, 1, 0});  // barrelchest anchor (bh) — Sunder +25% (imbued, vs +10% base)
		final double[] abyDagger = {0.85, 2, 0};
		SPEC_MAX.put(13265, abyDagger); // abyssal dagger
		SPEC_MAX.put(13267, abyDagger); // abyssal dagger(p)
		SPEC_MAX.put(13269, abyDagger); // abyssal dagger(p+)
		SPEC_MAX.put(13271, abyDagger); // abyssal dagger(p++)
		final double[] abyDaggerBh = {0.95, 2, 0}; // imbue eases the spec damage penalty to -5% (vs the base -15%)
		SPEC_MAX.put(27861, abyDaggerBh); // abyssal dagger (bh)
		SPEC_MAX.put(27863, abyDaggerBh); // abyssal dagger (bh)(p)
		SPEC_MAX.put(27865, abyDaggerBh); // abyssal dagger (bh)(p+)
		SPEC_MAX.put(27867, abyDaggerBh); // abyssal dagger (bh)(p++)
		SPEC_MAX.put(20849, new double[]{1.0, 1, 0});   // dragon thrownaxe (accuracy-only)
		SPEC_MAX.put(3204, new double[]{1.1, 1, 0});    // dragon halberd
		SPEC_MAX.put(23987, new double[]{1.1, 1, 0});   // crystal halberd
	}

	/** Reads all game state on the client thread; the returned value is immutable. */
	private final Client client;
	private final ItemManager itemManager;
	// Change-detection for the spec debug line (client thread only).
	private boolean lastSpecActive;
	private int lastSpecWeapon = -1;

	CombatCalc(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	// The combat class the player's selected style attacks with.
	enum Style
	{
		MELEE, RANGED, MAGIC, OTHER
	}

	/** One coherent read of the player's own numbers; fields final for EDT safety. */
	static final class MaxHitInfo
	{
		final Style style;
		final String styleName;   // display text, e.g. "Melee" or "Ranged (atlatl)"
		final int maxHit;         // -1 = spell-based (magic), unknown
		final boolean specActive; // the special-attack bar is lit
		final int specMaxHit;     // spec ceiling (-1 = weapon not in the table)
		final int specHits;       // hits per spec (2 for dds, etc.)
		final boolean specTotal;  // specMaxHit is the whole combo's ceiling (claws)

		MaxHitInfo(Style style, String styleName, int maxHit, boolean specActive, int specMaxHit,
			int specHits, boolean specTotal)
		{
			this.style = style;
			this.styleName = styleName;
			this.maxHit = maxHit;
			this.specActive = specActive;
			this.specMaxHit = specMaxHit;
			this.specHits = specHits;
			this.specTotal = specTotal;
		}

		/** True when the max-hit line should show the special-attack number. */
		boolean specShown()
		{
			return specActive && specMaxHit >= 0;
		}

		/** Display text for the max-hit line: "34", "2× 27", "up to 68", "spell-based". */
		String maxHitText()
		{
			if (maxHit < 0)
			{
				return "spell-based";
			}
			final int shown = specShown() ? specMaxHit : maxHit;
			return specShown() && specTotal ? "up to " + shown
				: specShown() && specHits > 1 ? specHits + "× " + shown
				: Integer.toString(shown);
		}
	}

	/** Compute the player's current max hit. Client thread only. */
	MaxHitInfo ownMaxHit()
	{
		final Stance stance = currentStance();
		final Bonuses mine = worn();
		final int weaponId = wornWeaponId();

		final Style style = stance.style;
		int maxHit = -1;
		String styleName;
		switch (style)
		{
			case MELEE:
			{
				styleName = "Melee";
				final int effStr = effectiveLevel(client.getBoostedSkillLevel(Skill.STRENGTH),
					strengthPrayerMult(), stance.strengthBonus);
				maxHit = maxHit(effStr, mine.str);
				break;
			}
			case RANGED:
			{
				if (weaponId == ECLIPSE_ATLATL)
				{
					// The atlatl's damage rides the STRENGTH level (visible boosts included) and
					// the gear's MELEE strength bonus, while ranged prayers boost the damage and
					// melee prayers do nothing — the wiki-documented one-off among ranged weapons.
					styleName = "Ranged (atlatl)";
					final int effStr = effectiveLevel(client.getBoostedSkillLevel(Skill.STRENGTH),
						rangedStrengthPrayerMult(), stance.rangedBonus);
					maxHit = maxHit(effStr, mine.str);
				}
				else
				{
					styleName = "Ranged";
					final int effStr = effectiveLevel(client.getBoostedSkillLevel(Skill.RANGED),
						rangedStrengthPrayerMult(), stance.rangedBonus);
					maxHit = maxHit(effStr, mine.rstr);
				}
				break;
			}
			case MAGIC:
				styleName = "Magic";
				maxHit = -1; // spell-dependent — shown as such rather than guessed
				break;
			default:
				styleName = "—";
				break;
		}

		// With the special-attack bar lit, the max-hit line switches to the spec's ceiling for
		// the known PvP spec weapons.
		final boolean specActive = client.getVarpValue(VarPlayerID.SA_ATTACK) == 1;
		int specMaxHit = -1;
		int specHits = 1;
		boolean specTotal = false;
		if (specActive && maxHit >= 0)
		{
			final double[] spec = SPEC_MAX.get(weaponId);
			if (spec != null)
			{
				double mult = spec[0];
				if ((weaponId == DARK_BOW || weaponId == DARK_BOW_BH) && wornAmmoIsDragonArrow())
				{
					mult = 1.5; // the dark bow spec jumps from 30% to 50% with dragon arrows
				}
				specMaxHit = (int) (maxHit * mult);
				specHits = (int) spec[1];
				specTotal = spec[2] == 1;
			}
		}
		if (specActive != lastSpecActive || weaponId != lastSpecWeapon)
		{
			// Change-only, so a missed table entry shows up in the dev log instead of silently
			// displaying the normal max (how the BH dragon mace gap was found).
			lastSpecActive = specActive;
			lastSpecWeapon = weaponId;
			log.debug("spec state: active={} weapon={} specMax={}", specActive, weaponId, specMaxHit);
		}

		return new MaxHitInfo(style, styleName, maxHit, specActive, specMaxHit, specHits, specTotal);
	}

	// --- The player's selected combat style, from the game's own weapon-style data ---

	private static final class Stance
	{
		final Style style;
		final int strengthBonus; // melee aggressive +3 / controlled +1
		final int rangedBonus;   // ranged accurate +3 (indistinguishable from rapid — kept at 0)

		Stance(Style style, int strengthBonus, int rangedBonus)
		{
			this.style = style;
			this.strengthBonus = strengthBonus;
			this.rangedBonus = rangedBonus;
		}
	}

	/**
	 * Resolve the selected attack style exactly like the core Attack Styles plugin: weapon
	 * category varbit → WEAPON_STYLES enum → style structs, with the defensive-autocast offset.
	 */
	private Stance currentStance()
	{
		final int weaponType = client.getVarbitValue(VarbitID.COMBAT_WEAPON_CATEGORY);
		int idx = client.getVarpValue(VarPlayerID.COM_MODE);
		final String[] styles = weaponStyleNames(weaponType);
		if (idx == 4)
		{
			idx += client.getVarbitValue(VarbitID.AUTOCAST_DEFMODE);
		}
		final String name = idx >= 0 && idx < styles.length && styles[idx] != null ? styles[idx] : "";
		switch (name)
		{
			case "Accurate":
				return new Stance(Style.MELEE, 0, 0);
			case "Aggressive":
				return new Stance(Style.MELEE, 3, 0);
			case "Controlled":
				return new Stance(Style.MELEE, 1, 0);
			case "Defensive":
				return new Stance(Style.MELEE, 0, 0);
			case "Ranging":
				// Covers both the accurate (+3) and rapid (+0) styles — the game data doesn't
				// distinguish them here. Rapid is the PvP norm, so no bonus is applied.
				return new Stance(Style.RANGED, 0, 0);
			case "Longrange":
				return new Stance(Style.RANGED, 0, 0);
			case "Casting":
			case "Defensive casting":
				return new Stance(Style.MAGIC, 0, 0);
			default:
				return new Stance(Style.OTHER, 0, 0);
		}
	}

	private String[] weaponStyleNames(int weaponType)
	{
		// from script4525, as read by the core Attack Styles plugin
		final int weaponStyleEnum = client.getEnum(EnumID.WEAPON_STYLES).getIntValue(weaponType);
		if (weaponStyleEnum == -1)
		{
			if (weaponType == 22) // blue moon spear
			{
				return new String[]{"Accurate", "Aggressive", null, "Defensive", "Casting", "Defensive casting"};
			}
			if (weaponType == 30) // partisan
			{
				return new String[]{"Accurate", "Aggressive", "Aggressive", "Defensive"};
			}
			return new String[0];
		}
		final EnumComposition styleEnum = client.getEnum(weaponStyleEnum);
		final int[] structs = styleEnum.getIntVals();
		final String[] names = new String[structs.length];
		for (int i = 0; i < structs.length; i++)
		{
			final StructComposition struct = client.getStructComposition(structs[i]);
			String name = struct.getStringValue(ParamID.ATTACK_STYLE_NAME);
			if (i == 5 && "Defensive".equals(name))
			{
				name = "Defensive casting";
			}
			names[i] = name;
		}
		return names;
	}

	// --- Equipment bonuses (own worn gear) ---

	private static final class Bonuses
	{
		int str, rstr;
	}

	private int wornWeaponId()
	{
		final ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		final Item weapon = worn == null ? null
			: worn.getItem(net.runelite.api.EquipmentInventorySlot.WEAPON.getSlotIdx());
		return weapon == null ? -1 : weapon.getId();
	}

	private boolean wornAmmoIsDragonArrow()
	{
		final ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		final Item ammo = worn == null ? null
			: worn.getItem(net.runelite.api.EquipmentInventorySlot.AMMO.getSlotIdx());
		if (ammo == null || ammo.getId() <= 0)
		{
			return false;
		}
		try
		{
			return itemManager.getItemComposition(ammo.getId()).getName()
				.toLowerCase().contains("dragon arrow");
		}
		catch (RuntimeException e)
		{
			return false;
		}
	}

	private Bonuses worn()
	{
		final Bonuses b = new Bonuses();
		final ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn != null)
		{
			for (final Item item : worn.getItems())
			{
				if (item.getId() > 0)
				{
					final ItemStats stats = itemManager.getItemStats(item.getId());
					final ItemEquipmentStats e = stats == null ? null : stats.getEquipment();
					if (e != null)
					{
						b.str += e.getStr();
						b.rstr += e.getRstr();
					}
				}
			}
		}
		return b;
	}

	// --- The player's active prayer multipliers (varbit reads, client thread) ---

	private double strengthPrayerMult()
	{
		if (on(VarbitID.PRAYER_PIETY))
		{
			return 1.23;
		}
		if (on(VarbitID.PRAYER_CHIVALRY))
		{
			return 1.18;
		}
		if (on(VarbitID.PRAYER_ULTIMATESTRENGTH))
		{
			return 1.15;
		}
		if (on(VarbitID.PRAYER_SUPERHUMANSTRENGTH))
		{
			return 1.10;
		}
		if (on(VarbitID.PRAYER_BURSTOFSTRENGTH))
		{
			return 1.05;
		}
		return 1;
	}

	private double rangedStrengthPrayerMult()
	{
		if (on(VarbitID.PRAYER_RIGOUR))
		{
			return 1.23;
		}
		if (on(VarbitID.PRAYER_DEADEYE))
		{
			return 1.18;
		}
		if (on(VarbitID.PRAYER_EAGLEEYE))
		{
			return 1.15;
		}
		if (on(VarbitID.PRAYER_HAWKEYE))
		{
			return 1.10;
		}
		if (on(VarbitID.PRAYER_SHARPEYE))
		{
			return 1.05;
		}
		return 1;
	}

	private boolean on(int varbit)
	{
		return client.getVarbitValue(varbit) == 1;
	}

	// --- Pure formula pieces (unit-tested) ---

	/** effective level = floor(boosted × prayer) + stance + 8 */
	static int effectiveLevel(int boostedLevel, double prayerMult, int stanceBonus)
	{
		return (int) (boostedLevel * prayerMult) + stanceBonus + 8;
	}

	/** roll = effective × (equipment bonus + 64) */
	static int attackRoll(int effectiveLevel, int equipmentBonus)
	{
		return effectiveLevel * (equipmentBonus + 64);
	}

	/** The standard OSRS accuracy formula. */
	static double hitChance(int attackRoll, int defenceRoll)
	{
		if (attackRoll < 0 || defenceRoll < 0)
		{
			return 0;
		}
		if (attackRoll > defenceRoll)
		{
			return 1d - (defenceRoll + 2d) / (2d * (attackRoll + 1d));
		}
		return attackRoll / (2d * (defenceRoll + 1d));
	}

	/** max hit = floor(0.5 + effective × (strength bonus + 64) / 640) */
	static int maxHit(int effectiveLevel, int strengthBonus)
	{
		return (effectiveLevel * (strengthBonus + 64) + 320) / 640;
	}

	/** Super combat / super defence boost: 5 + 15% of the level. */
	static int superCombatBoost(int level)
	{
		return 5 + (int) (level * 0.15);
	}

	/** The best defensive prayer multiplier a given Prayer level allows. */
	static double defensivePrayerMult(int prayerLevel)
	{
		if (prayerLevel >= 70)
		{
			return 1.25;
		}
		if (prayerLevel >= 60)
		{
			return 1.20;
		}
		if (prayerLevel >= 28)
		{
			return 1.15;
		}
		if (prayerLevel >= 13)
		{
			return 1.10;
		}
		if (prayerLevel >= 1)
		{
			return 1.05;
		}
		return 1;
	}

	/** PvP protection prayers block 40% — the shown hit lands at 60%. */
	static int afterOverhead(int maxHit)
	{
		return maxHit * 6 / 10;
	}
}

package com.anonyser.pvpprofittracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import net.runelite.api.MenuAction;
import net.runelite.client.ui.overlay.OverlayMenuEntry;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Pops up when you and a focused opponent die within a few ticks of each other (a "double death").
 * It stays on screen until you say how much you looted back: right-click gives "Enter recovered"
 * (opens a number entry that adds to session + baseline profit) and "Dismiss" (nothing recovered).
 * Movable, so it can be parked out of the way of the fight.
 */
class DoubleDeathOverlay extends OverlayPanel
{
	static final String ENTER = "Enter recovered";
	static final String DISMISS = "Dismiss";
	static final String TARGET = "Double death";

	private static final Color ALERT = new Color(255, 80, 80);
	private static final Color ALERT_DIM = new Color(150, 40, 40);

	private final PvpProfitTrackerPlugin plugin;
	private final PvpProfitTrackerConfig config;

	DoubleDeathOverlay(PvpProfitTrackerPlugin plugin, PvpProfitTrackerConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
		setMovable(true);
		getMenuEntries().add(new OverlayMenuEntry(MenuAction.RUNELITE_OVERLAY, ENTER, TARGET));
		getMenuEntries().add(new OverlayMenuEntry(MenuAction.RUNELITE_OVERLAY, DISMISS, TARGET));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		final String name = plugin.pendingDoubleDeathName();
		if (name == null || !config.showDoubleDeath())
		{
			return null;
		}
		// Flash the title so it is hard to miss mid-fight.
		final boolean on = (System.currentTimeMillis() / 500) % 2 == 0;
		panelComponent.getChildren().clear();
		panelComponent.setPreferredSize(new Dimension(180, 0));
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("DOUBLE DEATH")
			.color(on ? ALERT : ALERT_DIM)
			.build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("vs")
			.right(name)
			.build());
		panelComponent.getChildren().add(LineComponent.builder()
			.left("looted back?")
			.right("→ side panel")
			.build());
		return super.render(graphics);
	}
}

package com.anonyser.pvpprofittracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;

/**
 * The fight opponent's current hitpoints, live as the health bar moves: green while they're above
 * half, red below, white when unknown. Shows the number, the percent, or both (config). Movable
 * and resizable; outside a fight it renders nothing except while Alt is held, when the empty box
 * shows so it can be placed.
 */
class OpponentHpOverlay extends Overlay
{
	private static final Color HIGH = new Color(60, 220, 90);
	private static final Color LOW = new Color(235, 70, 60);
	private static final Dimension DEFAULT_SIZE = new Dimension(110, 30);

	private final Client client;
	private final PvpProfitTrackerPlugin plugin;
	private final PvpProfitTrackerConfig config;

	OpponentHpOverlay(Client client, PvpProfitTrackerPlugin plugin, PvpProfitTrackerConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.BOTTOM_RIGHT);
		setMovable(true);
		setResizable(true);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.showOppHpOverlay())
		{
			return null;
		}
		final PvpProfitTrackerPlugin.FightHud hud = plugin.fightHud();
		final boolean placing = client.isKeyPressed(KeyCode.KC_ALT);
		if (hud == null && !placing)
		{
			return null;
		}
		final Dimension size = getPreferredSize() != null ? getPreferredSize() : DEFAULT_SIZE;
		g.setColor(ComponentConstants.STANDARD_BACKGROUND_COLOR);
		g.fillRect(0, 0, size.width, size.height);
		if (hud != null)
		{
			final String text = hpText(hud);
			final Color color = hud.hpPct < 0 ? Color.WHITE : hud.hpPct >= 50 ? HIGH : LOW;
			// A plain vector font with antialiasing: the game's bitmap font turns blocky scaled up.
			g.setRenderingHint(java.awt.RenderingHints.KEY_TEXT_ANTIALIASING,
				java.awt.RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			final float fontSize = Math.max(10f, Math.min(size.height - 8f, size.width / 5f));
			g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, Math.round(fontSize)));
			final FontMetrics fm = g.getFontMetrics();
			final int x = Math.max(2, (size.width - fm.stringWidth(text)) / 2);
			final int y = (size.height + fm.getAscent() - fm.getDescent()) / 2;
			g.setColor(Color.BLACK);
			g.drawString(text, x + 1, y + 1);
			g.setColor(color);
			g.drawString(text, x, y);
		}
		else
		{
			// Placing mode with no fight: name the box so it's clear what will show here.
			g.setRenderingHint(java.awt.RenderingHints.KEY_TEXT_ANTIALIASING,
				java.awt.RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
			final FontMetrics fm = g.getFontMetrics();
			final String label = "Opponent HP";
			final int x = Math.max(2, (size.width - fm.stringWidth(label)) / 2);
			final int y = (size.height + fm.getAscent() - fm.getDescent()) / 2;
			g.setColor(Color.LIGHT_GRAY);
			g.drawString(label, x, y);
		}
		return size;
	}

	/** The number needs their hiscore Hitpoints level; the percent only needs the health bar. */
	private String hpText(PvpProfitTrackerPlugin.FightHud hud)
	{
		final String hp = hud.hpVal >= 0 ? Integer.toString(hud.hpVal) : "?";
		final String pct = hud.hpPct >= 0 ? hud.hpPct + "%" : "?";
		switch (config.oppHpStyle())
		{
			case HITPOINTS:
				return hp;
			case PERCENT:
				return pct;
			case BOTH:
			default:
				return hp + " (" + pct + ")";
		}
	}
}

package com.anonyser.pvpprofittracker;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.List;

/**
 * The hit-by-hit breakdown of one recorded fight, keyed to its {@link FightHistory.Fight} by the
 * fight's end timestamp. Only fights that actually produced a Win/Loss/Draw entry keep a log, and
 * only the most recent {@link #MAX_LOGS} keep one at all — the one-line history holds far more
 * fights than the logs do, so old fights simply stop offering a breakdown. All lives in one global
 * config value as JSON. Pure data + helpers; persistence belongs to the plugin, rendering to the
 * breakdown window.
 */
final class FightLog
{
	/** Newest fights keep a full log; anything older loses its breakdown (the history line stays). */
	static final int MAX_LOGS = 25;

	/** One damage splat. The field names are the stored JSON schema — never rename them. */
	static final class Entry
	{
		int t;            // game ticks since the fight's first hit (~0.6s each)
		boolean me;       // true = your hit on them, false = their hit on you
		int weapon = -1;  // attacker's weapon item id when the hit landed, -1 unknown
		String wname;     // weapon name, resolved at record time on the client thread
		boolean spec;     // landed right after your spec energy dropped (your hits only)
		String tag;       // null, or "recoil"/"venge" when the amounts shape as a reflection
		int amount;       // damage on the splat (0 = blocked)
		int hp = -1;      // defender's HP once the tick settled: yours exact, theirs estimated

		Entry()
		{
			// Gson
		}
	}

	String name;      // opponent display name
	long ts;          // the matching Fight's end-timestamp (epoch ms) — the lookup key
	long startTs;     // epoch ms of the first hit, for the header
	int duration;     // ticks from first damage to the fight's end
	String outcome;   // "Win" / "Loss" / "Draw" at save time
	List<Entry> hits = new ArrayList<>();

	FightLog()
	{
		// Gson
	}

	/** Parse the stored JSON list; malformed or missing input is just an empty list. */
	static List<FightLog> parse(Gson gson, String json)
	{
		final List<FightLog> out = new ArrayList<>();
		if (json == null || json.isEmpty())
		{
			return out;
		}
		try
		{
			final FightLog[] arr = gson.fromJson(json, FightLog[].class);
			if (arr != null)
			{
				for (final FightLog l : arr)
				{
					if (l != null && l.name != null)
					{
						if (l.hits == null)
						{
							l.hits = new ArrayList<>();
						}
						out.add(l);
					}
				}
			}
		}
		catch (RuntimeException ex)
		{
			// Corrupt value — drop the breakdowns rather than take the plugin down.
		}
		return out;
	}

	static String serialize(Gson gson, List<FightLog> logs)
	{
		return gson.toJson(logs);
	}

	/** Append a log, dropping the oldest past the cap. */
	static void append(List<FightLog> logs, FightLog l)
	{
		logs.add(l);
		while (logs.size() > MAX_LOGS)
		{
			logs.remove(0);
		}
	}

	/** The log saved for the fight ending at this timestamp, or null. */
	static FightLog byTs(List<FightLog> logs, long ts)
	{
		for (int i = logs.size() - 1; i >= 0; i--)
		{
			if (logs.get(i).ts == ts)
			{
				return logs.get(i);
			}
		}
		return null;
	}

	/** "m:ss" from a tick count (~0.6s per tick). */
	static String clock(int ticks)
	{
		final int totalSeconds = (int) Math.round(ticks * 0.6);
		return (totalSeconds / 60) + ":" + String.format("%02d", totalSeconds % 60);
	}
}

package com.anonyser.pvpprofittracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;

/**
 * Live damage race for the current fight: your total in green, theirs in red — fed by the same
 * recorder the breakdowns use, so vengeance and recoil damage land on the right side. Movable and
 * resizable (the text scales with the box). Outside a fight it renders nothing, except while Alt
 * is held, when it shows its empty box so there is something to grab and place.
 */
class FightDamageOverlay extends Overlay
{
	private static final Color MINE = new Color(60, 220, 90);
	private static final Color THEIRS = new Color(235, 70, 60);
	private static final Dimension DEFAULT_SIZE = new Dimension(120, 30);

	private final Client client;
	private final PvpProfitTrackerPlugin plugin;
	private final PvpProfitTrackerConfig config;

	FightDamageOverlay(Client client, PvpProfitTrackerPlugin plugin, PvpProfitTrackerConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.BOTTOM_LEFT);
		setMovable(true);
		setResizable(true);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!config.showDamageOverlay())
		{
			return null;
		}
		final PvpProfitTrackerPlugin.FightHud hud = plugin.fightHud();
		final boolean placing = client.isKeyPressed(KeyCode.KC_ALT);
		if (hud == null && !placing)
		{
			return null;
		}
		final Dimension size = getPreferredSize() != null ? getPreferredSize() : DEFAULT_SIZE;
		g.setColor(ComponentConstants.STANDARD_BACKGROUND_COLOR);
		g.fillRect(0, 0, size.width, size.height);
		if (hud != null)
		{
			// A plain vector font with antialiasing: the game's bitmap font turns blocky scaled up.
			g.setRenderingHint(java.awt.RenderingHints.KEY_TEXT_ANTIALIASING,
				java.awt.RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			final float fontSize = Math.max(10f, Math.min(size.height - 8f, size.width / 5f));
			g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, Math.round(fontSize)));
			final FontMetrics fm = g.getFontMetrics();
			final String mine = Integer.toString(hud.mine);
			final String sep = " · ";
			final String theirs = Integer.toString(hud.theirs);
			final int total = fm.stringWidth(mine) + fm.stringWidth(sep) + fm.stringWidth(theirs);
			int x = Math.max(2, (size.width - total) / 2);
			final int y = (size.height + fm.getAscent() - fm.getDescent()) / 2;
			x = drawWithShadow(g, mine, x, y, MINE);
			x = drawWithShadow(g, sep, x, y, Color.WHITE);
			drawWithShadow(g, theirs, x, y, THEIRS);
		}
		else
		{
			// Placing mode with no fight: name the box so it's clear what will show here.
			g.setRenderingHint(java.awt.RenderingHints.KEY_TEXT_ANTIALIASING,
				java.awt.RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
			final FontMetrics fm = g.getFontMetrics();
			final String label = "Damage dealt";
			final int x = Math.max(2, (size.width - fm.stringWidth(label)) / 2);
			final int y = (size.height + fm.getAscent() - fm.getDescent()) / 2;
			g.setColor(Color.LIGHT_GRAY);
			g.drawString(label, x, y);
		}
		return size;
	}

	private static int drawWithShadow(Graphics2D g, String s, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(s, x + 1, y + 1);
		g.setColor(color);
		g.drawString(s, x, y);
		return x + g.getFontMetrics().stringWidth(s);
	}
}

package com.anonyser.pvpprofittracker;

import com.google.gson.Gson;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * Completed-fight history behind the side panel's Past Fights lists. A fight is recorded only
 * when a kill or death actually lands in the W/L record — your death with the focused opponent
 * in sight, or their death while focused — so ordinary attacks and abandoned encounters never
 * appear. The whole history lives in one global config value as JSON, oldest first, capped so
 * it can't grow without bound. Pure helpers only: persistence belongs to the plugin, rendering
 * to the panel.
 */
final class FightHistory
{
	/** Newest fights push the oldest out past this. */
	static final int MAX_FIGHTS = 500;

	private static final DateTimeFormatter EXACT =
		DateTimeFormatter.ofPattern("EEEE, d MMMM uuuu 'at' h:mm a", Locale.ENGLISH);

	private FightHistory()
	{
	}

	/** One completed fight. The field names are the stored JSON schema — never rename them. */
	static final class Fight
	{
		String name;      // opponent's display name as rendered in-game
		int cmb = -1;     // their combat level in the scene when the fight ended, -1 unknown
		boolean target;   // they were your Bounty Hunter target
		boolean bh;       // fought on a Bounty Hunter world (a non-target there is a rogue)
		boolean win;      // true = their death, false = yours
		boolean draw;     // double death: you both died within seconds (win is meaningless then).
		                  // Absent in pre-draw JSON, so old fights read as plain wins/losses.
		boolean noResult; // the fight went quiet with nobody dead — kept for review, never
		                  // counted in the W/L record (win is meaningless here too)
		long ts;          // epoch millis when the fight ended

		Fight()
		{
			// Gson
		}

		Fight(String name, int cmb, boolean target, boolean bh, boolean win, long ts)
		{
			this.name = name;
			this.cmb = cmb;
			this.target = target;
			this.bh = bh;
			this.win = win;
			this.ts = ts;
		}

		/** "Win" / "Loss" / "Draw" / "No result" for chips and rows. */
		String outcomeText()
		{
			return draw ? "Draw" : noResult ? "No result" : win ? "Win" : "Loss";
		}
	}

	/**
	 * Collapse a double death into one draw: remove the most recent win and loss vs this name
	 * within the pair window and append a single draw entry carrying the EARLIER entry's
	 * timestamp (the fight log, if one was saved, is keyed by that ts). Returns the draw, or
	 * null when the expected pair isn't there (nothing is changed then).
	 */
	static Fight mergeDoubleDeath(List<Fight> fights, String name, long windowMs)
	{
		int winIdx = -1;
		int lossIdx = -1;
		for (int i = fights.size() - 1; i >= 0 && (winIdx < 0 || lossIdx < 0); i--)
		{
			final Fight f = fights.get(i);
			// No-result entries carry win=false but were never a death — they can't be the pair.
			if (f.draw || f.noResult || !f.name.equalsIgnoreCase(name))
			{
				continue;
			}
			if (f.win && winIdx < 0)
			{
				winIdx = i;
			}
			else if (!f.win && lossIdx < 0)
			{
				lossIdx = i;
			}
		}
		if (winIdx < 0 || lossIdx < 0
			|| Math.abs(fights.get(winIdx).ts - fights.get(lossIdx).ts) > windowMs)
		{
			return null;
		}
		final Fight a = fights.get(winIdx);
		final Fight b = fights.get(lossIdx);
		final Fight earlier = a.ts <= b.ts ? a : b;
		final Fight drawFight = new Fight(earlier.name, Math.max(a.cmb, b.cmb),
			a.target || b.target, a.bh || b.bh, false, earlier.ts);
		drawFight.draw = true;
		fights.remove(Math.max(winIdx, lossIdx));
		fights.remove(Math.min(winIdx, lossIdx));
		fights.add(drawFight);
		return drawFight;
	}

	/** Parse the stored JSON list; malformed or missing input is just an empty history. */
	static List<Fight> parse(Gson gson, String json)
	{
		final List<Fight> out = new ArrayList<>();
		if (json == null || json.isEmpty())
		{
			return out;
		}
		try
		{
			final Fight[] arr = gson.fromJson(json, Fight[].class);
			if (arr != null)
			{
				for (final Fight f : arr)
				{
					if (f != null && f.name != null)
					{
						out.add(f);
					}
				}
			}
		}
		catch (RuntimeException ex)
		{
			// Corrupt value — start fresh rather than take the panel down with it.
		}
		return out;
	}

	static String serialize(Gson gson, List<Fight> fights)
	{
		return gson.toJson(fights);
	}

	/** Append a fight, dropping the oldest past the cap. */
	static void append(List<Fight> fights, Fight f)
	{
		fights.add(f);
		while (fights.size() > MAX_FIGHTS)
		{
			fights.remove(0);
		}
	}

	/** "Sunday, 12 July 2026 at 3:45 PM" in the machine's own timezone. */
	static String exact(long ts)
	{
		return exact(ts, ZoneId.systemDefault());
	}

	static String exact(long ts, ZoneId zone)
	{
		return EXACT.format(Instant.ofEpochMilli(ts).atZone(zone));
	}

	/** "1 hour 30 minutes ago" — the two largest non-zero units; under a minute is "just now". */
	static String relative(long nowMs, long ts)
	{
		final long seconds = Math.max(0, (nowMs - ts) / 1000);
		if (seconds < 60)
		{
			return "just now";
		}
		final long minutes = seconds / 60;
		final long hours = minutes / 60;
		final long days = hours / 24;
		if (days > 0)
		{
			final long restHours = hours % 24;
			return unit(days, "day") + (restHours > 0 ? " " + unit(restHours, "hour") : "") + " ago";
		}
		if (hours > 0)
		{
			final long restMinutes = minutes % 60;
			return unit(hours, "hour") + (restMinutes > 0 ? " " + unit(restMinutes, "minute") : "")
				+ " ago";
		}
		return unit(minutes, "minute") + " ago";
	}

	private static String unit(long n, String word)
	{
		return n + " " + word + (n == 1 ? "" : "s");
	}

	/**
	 * Exact combat level (the game floors it for display): 0.25 × (def + hp + ⌊prayer/2⌋) plus
	 * the best of melee 0.325 × (att + str), ranged 0.325 × ⌊3·ranged/2⌋ and magic
	 * 0.325 × ⌊3·magic/2⌋. -1 unless all seven stats are known.
	 */
	static double combatLevel(int attack, int strength, int defence, int ranged, int magic,
		int hitpoints, int prayer)
	{
		if (attack <= 0 || strength <= 0 || defence <= 0 || ranged <= 0
			|| magic <= 0 || hitpoints <= 0 || prayer <= 0)
		{
			return -1;
		}
		final double base = 0.25 * (defence + hitpoints + prayer / 2);
		final double melee = 0.325 * (attack + strength);
		final double range = 0.325 * (ranged + ranged / 2);
		final double mage = 0.325 * (magic + magic / 2);
		return base + Math.max(melee, Math.max(range, mage));
	}
}

package com.anonyser.pvpprofittracker;

import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * How large gp values are displayed: full numbers (1,428,638) or compact (1.428M / 900M / 1.428B).
 */
public enum GpFormat
{
	FULL("Full numbers"),
	COMPACT("Compact (1.428M)");

	private final String label;

	GpFormat(String label)
	{
		this.label = label;
	}

	@Override
	public String toString()
	{
		return label;
	}

	String format(long v)
	{
		if (this == FULL)
		{
			return String.format("%,d", v);
		}
		final long a = Math.abs(v);
		if (a >= 1_000_000_000L)
		{
			return scaled(v, 1_000_000_000L, 3) + "B";
		}
		if (a >= 1_000_000L)
		{
			return scaled(v, 1_000_000L, 3) + "M";
		}
		if (a >= 100_000L)
		{
			return scaled(v, 1_000L, 1) + "K";
		}
		return String.format("%,d", v);
	}

	/** value/divisor with up to maxDecimals decimals, truncated, trailing zeros trimmed: 1.428, 900. */
	private static String scaled(long v, long divisor, int maxDecimals)
	{
		return BigDecimal.valueOf(v)
			.divide(BigDecimal.valueOf(divisor), maxDecimals, RoundingMode.DOWN)
			.stripTrailingZeros()
			.toPlainString();
	}

	/**
	 * Parse a user-typed gp amount, accepting the shorthand people actually read: plain digits
	 * ("4000000"), grouping commas or spaces ("4,000,000"), and k/m/b suffixes with an optional
	 * decimal ("4m", "4000k", "4.5m", "4 mil"). K = thousand, M = million, B = billion,
	 * case-insensitive; a trailing "gp" is ignored. Anything unparseable, empty or negative is 0.
	 */
	static long parseGp(String raw)
	{
		if (raw == null)
		{
			return 0;
		}
		// Drop grouping separators and spaces, lower-case the unit, and ignore a trailing "gp".
		String s = raw.trim().toLowerCase().replace(",", "").replace("_", "").replace(" ", "");
		if (s.endsWith("gp"))
		{
			s = s.substring(0, s.length() - 2);
		}
		if (s.isEmpty())
		{
			return 0;
		}
		// A trailing run of letters is the unit; its first letter picks the multiplier.
		long mult = 1;
		int end = s.length();
		while (end > 0 && Character.isLetter(s.charAt(end - 1)))
		{
			end--;
		}
		if (end < s.length())
		{
			switch (s.charAt(end))
			{
				case 'k':
					mult = 1_000L;
					break;
				case 'm':
					mult = 1_000_000L;
					break;
				case 'b':
					mult = 1_000_000_000L;
					break;
				default:
					return 0;
			}
			s = s.substring(0, end);
		}
		if (s.isEmpty())
		{
			return 0;
		}
		try
		{
			if (s.indexOf('.') >= 0)
			{
				final double val = Double.parseDouble(s);
				if (val < 0)
				{
					return 0;
				}
				final double gp = val * mult;
				return gp >= (double) Long.MAX_VALUE ? Long.MAX_VALUE : (long) Math.floor(gp);
			}
			final long val = Long.parseLong(s);
			if (val < 0)
			{
				return 0;
			}
			return val > Long.MAX_VALUE / mult ? Long.MAX_VALUE : val * mult;
		}
		catch (NumberFormatException ex)
		{
			return 0;
		}
	}
}

package com.anonyser.pvpprofittracker;

/**
 * A mutable tally for one tracking mode (session / baseline; "actual" uses only kills and deaths).
 * All gp values are in coins. Profit is event-sourced: loot-key gains plus crate rewards and any
 * double-death recovery, minus what's lost on death, minus consumables used in PvP — never a
 * net-worth diff.
 */
class Stats
{
	long kills;
	long deaths;
	long gainedGp;      // loot keys claimed
	long lostToDeathGp; // risk lost on our deaths
	long consumedGp;    // food / potions used in PvP
	long recoveredGp;   // gp looted back after a double death (manual entry)
	long crates;        // Bounty Hunter crates received
	long crateGp;       // value looted from opened Bounty Hunter crates
	long points;        // Bounty Hunter points gained

	long profit()
	{
		return gainedGp + crateGp + recoveredGp - lostToDeathGp - consumedGp;
	}

	double kd()
	{
		return deaths == 0 ? kills : (double) kills / deaths;
	}

	void addKill()
	{
		kills++;
	}

	void addGain(long gp)
	{
		gainedGp += gp;
	}

	void addDeath(long lostGp)
	{
		deaths++;
		lostToDeathGp += lostGp;
	}

	void addConsumed(long gp)
	{
		consumedGp += gp;
	}

	void addRecovered(long gp)
	{
		recoveredGp += gp;
	}

	void addCrates(int n)
	{
		crates += n;
	}

	void addCrateValue(long gp)
	{
		crateGp += gp;
	}

	void addPoints(long n)
	{
		points += n;
	}

	// Each tracker section resets independently (baseline K/D vs profit vs crates vs points).

	void resetKd()
	{
		kills = 0;
		deaths = 0;
	}

	void resetProfit()
	{
		gainedGp = 0;
		lostToDeathGp = 0;
		consumedGp = 0;
		recoveredGp = 0;
		crateGp = 0;
	}

	void resetCrates()
	{
		crates = 0;
	}

	void resetPoints()
	{
		points = 0;
	}

	void reset()
	{
		resetKd();
		resetProfit();
		resetCrates();
		resetPoints();
	}

	/** Copy another tally's values in place (null clears), keeping this object's identity stable. */
	void copyFrom(Stats o)
	{
		if (o == null)
		{
			reset();
			return;
		}
		kills = o.kills;
		deaths = o.deaths;
		gainedGp = o.gainedGp;
		lostToDeathGp = o.lostToDeathGp;
		consumedGp = o.consumedGp;
		recoveredGp = o.recoveredGp;
		crates = o.crates;
		crateGp = o.crateGp;
		points = o.points;
	}
}

