		body.add(opponentHolder);
		body.add(profitHolder);
		body.add(netWorthHolder);
		body.add(cratesHolder);
		body.add(pointsHolder);
		body.add(kdHolder);
		body.add(holder(resets));
		body.add(tip);

		refresh();
