		/** The exact end time, then a live "x ago" line registered on the given updater list. */
		private void addTimestampLines(JPanel p, FightHistory.Fight f, List<Runnable> updaters)
		{
			final JLabel when = smallLabel(FightHistory.exact(f.ts));
			when.setToolTipText(FightHistory.exact(f.ts));
			p.add(lineRow(when, null));
			final JLabel rel = smallLabel("");
			final Runnable update = () ->
				rel.setText(FightHistory.relative(System.currentTimeMillis(), f.ts));
			update.run();
			updaters.add(update);
			p.add(lineRow(rel, null));
		}

		/** Marks the fight type: green skull = your BH target, red skull = a BH-world rogue. */
		private void fightIcon(JLabel label, FightHistory.Fight f)
		{
			if (f.target)
			{
				plugin.spriteIcon(label,
					net.runelite.client.hiscore.HiscoreSkill.BOUNTY_HUNTER_HUNTER.getSpriteId(), 12);
				label.setToolTipText("They were your Bounty Hunter target");
			}
			else if (f.bh)
			{
				plugin.spriteIcon(label,
					net.runelite.client.hiscore.HiscoreSkill.BOUNTY_HUNTER_ROGUE.getSpriteId(), 12);
				label.setToolTipText("Bounty Hunter world — not your assigned target");
			}
		}

		private void capHeight(JPanel p)
		{
			p.setMaximumSize(new Dimension(Integer.MAX_VALUE, p.getPreferredSize().height));
		}

		private JPanel lineRow(Component left, Component right)
		{
			final JPanel r = new JPanel(new BorderLayout());
			r.setOpaque(false);
			r.setAlignmentX(Component.LEFT_ALIGNMENT);
			r.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));
			r.add(left, BorderLayout.WEST);
			if (right != null)
			{
				r.add(right, BorderLayout.EAST);
			}
			return r;
		}

		private JLabel smallLabel(String text)
		{
			final JLabel l = new JLabel(text);
			l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			l.setFont(l.getFont().deriveFont(l.getFont().getSize2D() - 2f));
			return l;
		}

		private Component vGap(int height)
		{
			final JPanel gap = new JPanel();
			gap.setOpaque(false);
			gap.setPreferredSize(new Dimension(0, height));
			gap.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
			return gap;
		}

		/** Re-render every visible "x ago" label in place — no rebuild, no jitter. */
		void updateRelativeTimes()
		{
			if (globalList.isVisible())
			{
				for (final Runnable r : globalRelUpdaters)
				{
					r.run();
				}
			}
			if (perList.isVisible())
			{
				for (final Runnable r : perRelUpdaters)
				{
					r.run();
				}
			}
		}

		// ---- lookup autocomplete ----

		private void refreshSuggestions()
		{
			if (applyingSuggestion)
			{
				return;
			}
			final String q = lookupField.getText().trim();
			suggestions.clear();
			suggestSel = -1;
			if (!q.isEmpty())
			{
				final String lq = q.toLowerCase();
				final List<String> known = plugin.knownNames();
				for (final String n : known) // prefix matches rank first
				{
					if (suggestions.size() < 8 && n.toLowerCase().startsWith(lq)
						&& !n.equalsIgnoreCase(q))
					{
						suggestions.add(n);
					}
				}
				for (final String n : known)
				{
					if (suggestions.size() < 8 && !n.toLowerCase().startsWith(lq)
						&& n.toLowerCase().contains(lq) && !n.equalsIgnoreCase(q))
					{
						suggestions.add(n);
					}
				}
			}
			suggestPopup.setVisible(false);
			suggestPopup.removeAll();
			if (suggestions.isEmpty())
			{
				return;
			}
			for (int i = 0; i < suggestions.size(); i++)
			{
				suggestPopup.add(suggestionRow(suggestions.get(i), i));
			}
			suggestPopup.show(lookupField, 0, lookupField.getHeight());
		}

		/**
		 * One suggestion: the name (click or Enter to complete) with a ✕ on the right that
		 * forgets the name — mistyped lookups get remembered, and this is how you evict them.
		 */
		private Component suggestionRow(final String name, final int index)
		{
			final JPanel row = new JPanel(new BorderLayout(6, 0));
			row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			row.setBorder(new EmptyBorder(3, 6, 3, 6));
			final JLabel nameLabel = new JLabel(name);
			nameLabel.setForeground(VALUE_COLOR);
			final MouseAdapter pick = new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent e)
				{
					applySuggestion(name);
				}

				@Override
				public void mouseEntered(MouseEvent e)
				{
					suggestSel = index;
					highlightSuggestion();
				}
			};
			row.addMouseListener(pick);
			nameLabel.addMouseListener(pick);
			final JLabel forget = new JLabel("✕");
			forget.setForeground(ColorScheme.LIGHT_GRAY_COLOR.darker());
			forget.setToolTipText("Forget this name");
			forget.setCursor(new Cursor(Cursor.HAND_CURSOR));
			forget.addMouseListener(new MouseAdapter()
			{
				@Override
				public void mousePressed(MouseEvent e)
				{
					plugin.forgetName(name);
					refreshSuggestions(); // re-show the popup without it
				}

				@Override
				public void mouseEntered(MouseEvent e)
				{
					suggestSel = index;
					highlightSuggestion();
				}
			});
			row.add(nameLabel, BorderLayout.CENTER);
			row.add(forget, BorderLayout.EAST);
			return row;
		}

		private void highlightSuggestion()
		{
			for (int i = 0; i < suggestPopup.getComponentCount(); i++)
			{
				suggestPopup.getComponent(i).setBackground(i == suggestSel
					? ColorScheme.DARK_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);
			}
			suggestPopup.repaint();
		}

		/** Fill the field with the picked name — completing never submits the lookup. */
		private void applySuggestion(String name)
		{
			applyingSuggestion = true;
			lookupField.setText(name);
			applyingSuggestion = false;
			hideSuggestions();
			lookupField.requestFocusInWindow();
		}

		private void hideSuggestions()
		{
			suggestSel = -1;
			suggestions.clear();
			suggestPopup.setVisible(false);
		}

		private void populateGrid(int[] ids, String[] names, long[] prices)
		{
			wornGrid.removeAll();
			for (final int slot : cellSlot)
			{
				final JLabel cell = new JLabel();
				cell.setHorizontalAlignment(JLabel.CENTER);
				cell.setPreferredSize(new Dimension(38, 34));
				if (slot == -2)
				{
					// Ammo and ring exist on the real equipment tab but never render on another
					// player — crossed out rather than hidden so the layout reads at a glance.
					cell.setText("✕");
					cell.setForeground(ColorScheme.LIGHT_GRAY_COLOR.darker());
					cell.setToolTipText("Not visible on other players");
				}
				else if (slot >= 0 && ids != null && slot < ids.length && ids[slot] > 0)
				{
					cell.setToolTipText("<html>" + (names[slot] == null ? "?" : names[slot]) + "<br>"
						+ plugin.fmt(prices[slot]) + " (GE)</html>");
					plugin.itemIcon(ids[slot]).addTo(cell);
				}
				else if (slot >= 0)
				{
					cell.setToolTipText(slotNames[slot] + ": nothing visible");
				}
				wornGrid.add(cell);
			}
		}
	}
}

package com.anonyser.pvpprofittracker;

import java.util.ArrayList;
import java.util.List;

/**
 * Records one fight's hit-by-hit log while it happens. Deliberately client-free: the plugin does
 * every game read (weapons, HP, spec energy, hitsplat filtering) on the client thread and feeds
 * plain values in; this class only keeps the state machine and the log, so the tricky parts stay
 * unit-testable.
 *
 * <p>Damage lands mid-tick but HP settles at the end of it (a Vengeance heal or a second splat can
 * move it again), so entries buffer as "pending" and get their defender-HP filled in when the
 * plugin calls {@link #settle} from GameTick — which the client fires after the tick's hitsplats
 * have all applied.</p>
 *
 * <p>Reflection labelling reuses the shapes proven in live PvP testing: a Ring of Recoil reflection
 * is ceil(10%) of the hit that caused it and Vengeance is floor(75%), the reflection lands the same
 * tick, and the client can display it BEFORE its trigger — so both orders are checked. A
 * recoil-shaped splat on the opponent would be MY ring, which is checkable, so it is only labelled
 * when a reflect ring is actually worn; a suspected reflection on me is their (invisible) ring and
 * always labels; Vengeance can't be checked either way and always labels.</p>
 */
final class FightRecorder
{
	/** ~30s without damage abandons the log (the fight fizzled; nothing is saved). */
	static final int DISENGAGE_TICKS = 50;

	/** A marathon fight stops logging past this many splats — the stored JSON must stay sane. */
	static final int MAX_HITS = 500;

	private boolean active;
	private String name;
	private long startMs;
	private int startTick;
	private int lastDamageTick;
	private final List<FightLog.Entry> hits = new ArrayList<>();
	private final List<FightLog.Entry> pending = new ArrayList<>();
	// Running damage totals for the live overlay — counted for EVERY splat, even past MAX_HITS.
	private int totalMine;
	private int totalTheirs;

	boolean isActive()
	{
		return active;
	}

	String opponentName()
	{
		return name;
	}

	int totalMine()
	{
		return totalMine;
	}

	int totalTheirs()
	{
		return totalTheirs;
	}

	void start(String opponentName, long nowMs, int tick)
	{
		active = true;
		name = opponentName;
		startMs = nowMs;
		startTick = tick;
		lastDamageTick = tick;
		hits.clear();
		pending.clear();
		totalMine = 0;
		totalTheirs = 0;
	}

	/** One damage splat, already filtered and attributed by the plugin. */
	void onDamage(int tick, boolean byMe, int amount, int weaponId, String weaponName, boolean spec)
	{
		if (!active)
		{
			return;
		}
		lastDamageTick = tick; // even a beyond-cap hit keeps the fight alive for the outcome
		if (byMe)
		{
			totalMine += amount;
		}
		else
		{
			totalTheirs += amount;
		}
		if (hits.size() + pending.size() >= MAX_HITS)
		{
			return;
		}
		final FightLog.Entry e = new FightLog.Entry();
		e.t = tick - startTick;
		e.me = byMe;
		e.amount = amount;
		e.weapon = weaponId;
		e.wname = weaponName;
		e.spec = spec;
		pending.add(e);
	}

	/**
	 * Settle this tick's entries: label reflections, then stamp the defender's HP as it stands now
	 * that the tick's damage has fully applied. Call from GameTick (after the tick's hitsplats,
	 * before the next tick's). Either HP may be -1 (unknown) and is stored as-is.
	 */
	void settle(int myHp, int oppHp, boolean iWearReflectRing)
	{
		if (!active || pending.isEmpty())
		{
			return;
		}
		labelReflections(pending, iWearReflectRing);
		// The client can DISPLAY a reflection before the hit that caused it; store real hits
		// first so a tick always reads cause before effect.
		pending.sort((a, b) -> Boolean.compare(a.tag != null, b.tag != null));
		for (final FightLog.Entry e : pending)
		{
			// The defender is me for their hits, them for mine.
			e.hp = e.me ? oppHp : myHp;
			hits.add(e);
		}
		pending.clear();
	}

	/** True when the fight has gone quiet long enough to abandon. */
	boolean disengaged(int tick)
	{
		return active && tick - lastDamageTick > DISENGAGE_TICKS;
	}

	/** Ticks since the last damage either way; 0 when no fight is running. */
	int quietTicks(int tick)
	{
		return active ? Math.max(0, tick - lastDamageTick) : 0;
	}

	/**
	 * Close the log with its outcome. Unsettled entries keep hp = -1 rather than guessing.
	 * Returns null when nothing was ever recorded.
	 */
	FightLog finish(String outcome, long endTs, int endTick, boolean iWearReflectRing)
	{
		if (!active)
		{
			return null;
		}
		labelReflections(pending, iWearReflectRing);
		pending.sort((a, b) -> Boolean.compare(a.tag != null, b.tag != null));
		hits.addAll(pending);
		pending.clear();
		final FightLog log = new FightLog();
		log.name = name;
		log.ts = endTs;
		log.startTs = startMs;
		log.duration = Math.max(0, endTick - startTick);
		log.outcome = outcome;
		log.hits.addAll(hits);
		discard();
		return log.hits.isEmpty() ? null : log;
	}

	void discard()
	{
		active = false;
		name = null;
		hits.clear();
		pending.clear();
		totalMine = 0;
		totalTheirs = 0;
	}

	/**
	 * Within one tick's entries, find an opposite-side pair whose amounts shape as a reflection
	 * (checked in both display orders) and label the reflected splat instead of blaming a weapon.
	 */
	static void labelReflections(List<FightLog.Entry> tickEntries, boolean iWearReflectRing)
	{
		for (int i = 0; i < tickEntries.size(); i++)
		{
			for (int j = i + 1; j < tickEntries.size(); j++)
			{
				final FightLog.Entry a = tickEntries.get(i);
				final FightLog.Entry b = tickEntries.get(j);
				if (a.me == b.me || a.tag != null || b.tag != null)
				{
					continue;
				}
				char shape = reflectShape(a.amount, b.amount);
				FightLog.Entry reflected = b;
				if (shape == '-')
				{
					shape = reflectShape(b.amount, a.amount);
					reflected = a;
				}
				if (shape == '-')
				{
					continue;
				}
				// A recoil-shaped splat on the opponent would be my own ring — only credible
				// when a reflect ring is actually worn. Their ring / either Vengeance can't be
				// checked, so those always label.
				if (shape == 'R' && reflected.me && !iWearReflectRing)
				{
					continue;
				}
				reflected.tag = shape == 'R' ? "recoil" : "venge";
				reflected.weapon = -1;
				reflected.wname = null;
				reflected.spec = false;
			}
		}
	}

	/** 'R' if second is ceil(10%) of first (Ring of Recoil), 'V' if floor(75%) (Vengeance). */
	static char reflectShape(int firstAmt, int secondAmt)
	{
		if (firstAmt <= 0 || secondAmt <= 0)
		{
			return '-';
		}
		if (secondAmt == (firstAmt + 9) / 10)
		{
			return 'R';
		}
		if (secondAmt == (int) (firstAmt * 0.75))
		{
			return 'V';
		}
		return '-';
	}
}

package com.anonyser.pvpprofittracker;

import java.util.ArrayDeque;
import java.util.Deque;

/**
 * The attacks I have thrown that haven't landed yet. Client-free like {@link FightRecorder}: the
 * plugin does every game read (worn weapon, projectile cycles, spec energy) and feeds plain values
 * in, so the matching rules stay unit-testable.
 *
 * <p>A hitsplat is the effect of an attack that left up to a few ticks earlier, and the API gives a
 * splat no link back to its cause — {@code HitsplatApplied} carries an actor, a type and an amount,
 * nothing else. So the weapon and the spec flag have to be captured when the attack LEAVES and
 * matched by predicted landing tick. Reading the worn weapon when the splat lands is what put a
 * Dragon mace on a crossbow bolt that was still in the air.</p>
 *
 * <p>Records expire on their own once their window closes, claimed or not. A shot the opponent
 * teleported away from must never sit at the head of the queue and shift every later hit by one for
 * the rest of the fight — that would be worse than the bug it replaces, because it would be wrong
 * consistently instead of occasionally.</p>
 */
final class AttackQueue
{
	/** 600ms game tick over 20ms client cycles. */
	static final int CYCLES_PER_TICK = 30;

	/**
	 * RuneLite core (SpecialWeapon#getHitDelay): every attack carries one server cycle of delay
	 * beyond its projectile travel time. Integer division, no rounding — the server does none.
	 */
	static final int HIT_DELAY_BASE = 1;

	/**
	 * When the defender is processed before the attacker the hit slips a tick. One tick of grace
	 * absorbs that. More would re-open the theft window this class exists to close.
	 */
	static final int GRACE_TICKS = 1;

	/** An instant spec applies on its own tick or the next; nothing projectile-free waits longer. */
	static final int MELEE_GRACE_TICKS = 1;

	/** Nothing sane is airborne this long — a garbage endCycle must not park a record in the queue. */
	static final int MAX_FLIGHT_TICKS = 6;

	/** Two bolts and a spec can all be in the air at once. Thirty cannot. */
	static final int MAX_PENDING = 6;

	/** One thrown attack, waiting for its damage to arrive. */
	static final class Attack
	{
		int fireTick;        // the tick it left
		int landTick;        // first tick its damage can apply
		int lastTick;        // last tick it can be claimed on
		int weaponId = -1;   // read AT LAUNCH, so a mid-flight switch can't touch it
		String weaponName;
		boolean spec;
		boolean projectile;  // timing came from a real projectile, not the melee assumption
		int maxSplats = 1;   // one projectile carries one splat; an instant spec is unbounded
		int claims;
		int claimTick = Integer.MIN_VALUE;
	}

	private final Deque<Attack> q = new ArrayDeque<>();

	/** A shot with real flight timing, or null when the computed flight is nonsense. */
	static Attack projectile(int fireTick, int flightCycles, int weaponId, String weaponName,
		boolean spec)
	{
		if (flightCycles < 0)
		{
			return null;
		}
		final int delay = flightCycles / CYCLES_PER_TICK + HIT_DELAY_BASE;
		if (delay > MAX_FLIGHT_TICKS)
		{
			return null;
		}
		final Attack a = new Attack();
		a.fireTick = fireTick;
		a.landTick = fireTick + delay;
		a.lastTick = a.landTick + GRACE_TICKS;
		a.weaponId = weaponId;
		a.weaponName = weaponName;
		a.spec = spec;
		a.projectile = true;
		return a;
	}

	/**
	 * A spec with no projectile behind it (claws, dds, AGS, abyssal dagger, gmaul). Unbounded splat
	 * count, because those land two to four splats on the ONE tick and every one of them is the spec.
	 */
	static Attack instantSpec(int fireTick, int weaponId, String weaponName)
	{
		final Attack a = new Attack();
		a.fireTick = fireTick;
		a.landTick = fireTick;
		a.lastTick = fireTick + MELEE_GRACE_TICKS;
		a.weaponId = weaponId;
		a.weaponName = weaponName;
		a.spec = true;
		a.maxSplats = Integer.MAX_VALUE;
		return a;
	}

	void add(Attack a)
	{
		if (a == null)
		{
			return;
		}
		while (q.size() >= MAX_PENDING)
		{
			q.pollFirst();
		}
		q.addLast(a);
	}

	void clear()
	{
		q.clear();
	}

	int size()
	{
		return q.size();
	}

	/** The spec queued for this tick that no projectile has claimed yet, or null. */
	Attack unTimedSpecAt(int fireTick)
	{
		for (final Attack a : q)
		{
			if (a.spec && !a.projectile && a.fireTick == fireTick && a.claims == 0)
			{
				return a;
			}
		}
		return null;
	}

	/**
	 * The projectile turned up for a spec already queued this tick (voidwaker, ballista, blowpipe
	 * spec) — re-time the record we have rather than queue a second attack for the same swing.
	 */
	boolean retime(Attack a, int flightCycles)
	{
		final Attack timed = projectile(a.fireTick, flightCycles, a.weaponId, a.weaponName, true);
		if (timed == null)
		{
			return false;
		}
		a.landTick = timed.landTick;
		a.lastTick = timed.lastTick;
		a.projectile = true;
		a.maxSplats = 1; // one projectile carries one splat; the multi-splat licence was melee's
		return true;
	}

	/**
	 * The spec energy varp can arrive AFTER the projectile within one packet phase, so a shot
	 * already queued for this tick may turn out to have been the spec. True when it flagged one.
	 */
	boolean markSpec(int fireTick)
	{
		boolean any = false;
		for (final Attack a : q)
		{
			if (a.projectile && a.fireTick == fireTick && a.claims == 0 && !a.spec)
			{
				a.spec = true;
				any = true; // dark bow and MSB fire two arrows on one tick; both are the spec
			}
		}
		return any;
	}

	private static boolean eligible(Attack a, int tick)
	{
		if (a.claims == 0)
		{
			return tick >= a.landTick && tick <= a.lastTick;
		}
		// Already serving: only the extra splats of the SAME tick may share it, and only while the
		// record still has splats left. This is the old specTaggedTick, re-keyed from "this tick
		// number" to "this attack" — which is why a bolt passing through no longer gets tagged.
		return a.claims < a.maxSplats && tick == a.claimTick;
	}

	/**
	 * The attack this splat is the arrival of, or null when nothing explains it (ordinary melee,
	 * a bleed, someone else's damage). Oldest eligible record first.
	 */
	Attack claim(int tick)
	{
		expire(tick);
		// An unclaimed record wins over one already serving, so a fresh shot is never swallowed by
		// the multi-splat licence of the spec that landed alongside it.
		for (final Attack a : q)
		{
			if (a.claims == 0 && eligible(a, tick))
			{
				a.claims++;
				a.claimTick = tick;
				return a;
			}
		}
		for (final Attack a : q)
		{
			if (a.claims > 0 && eligible(a, tick))
			{
				a.claims++;
				return a;
			}
		}
		return null;
	}

	/**
	 * Hand a record back. A recoil or vengeance splat can claim an attack before the reflection
	 * labelling recognises it, and the genuine hit on that tick must still be able to take it.
	 */
	void release(Attack a)
	{
		if (a != null && a.claims > 0)
		{
			a.claims--;
		}
	}

	/** Drop records whose window has closed, so a shot that never landed can't shift later hits. */
	private void expire(int tick)
	{
		while (!q.isEmpty() && tick > q.peekFirst().lastTick)
		{
			q.pollFirst();
		}
	}
}

package com.anonyser.pvpprofittracker;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * On-screen overlay. Lines are grouped in a fixed order — K/D (actual, baseline, session), profit
 * (baseline, session), risk, net worth — with each line toggleable in the config.
 */
class PvpProfitTrackerOverlay extends OverlayPanel
{
	private static final Color FLASH_COLOR = new Color(255, 200, 60);
	private static final Color PROTECT_ON_COLOR = new Color(0, 200, 83);
	private static final Color PROTECT_OFF_COLOR = new Color(216, 60, 62);

	private final PvpProfitTrackerPlugin plugin;
	private final PvpProfitTrackerConfig config;

	@Inject
	PvpProfitTrackerOverlay(PvpProfitTrackerPlugin plugin, PvpProfitTrackerConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay())
		{
			return null;
		}

		panelComponent.getChildren().clear();
		panelComponent.setPreferredSize(new Dimension(185, 0));
		panelComponent.getChildren().add(TitleComponent.builder().text("PvP Profit").build());

		// Crate reward flash — mirrored here because mid-fight nobody is watching the side panel.
		if (plugin.crateFlashGp() > 0)
		{
			addLine("Crate reward", plugin.fmt(plugin.crateFlashGp())
				+ " (" + plugin.crateFlashSecondsLeft() + "s)", FLASH_COLOR);
		}

		if (config.showActualKd())
		{
			final Stats a = plugin.getActual();
			addLine("K/D (actual)",
				a.kills + a.deaths > 0 ? PvpProfitTrackerPlugin.kdText(a) : "—", null);
		}
		if (config.showBaselineKd())
		{
			addLine("K/D (baseline)", PvpProfitTrackerPlugin.kdText(plugin.getBaseline()), null);
		}
		if (config.showSessionKd())
		{
			addLine("K/D (session)", PvpProfitTrackerPlugin.kdText(plugin.getSession()), null);
		}
		if (config.showBaselineProfit())
		{
			addProfitLine("Profit (baseline)", plugin.getBaseline().profit());
		}
		if (config.showSessionProfit())
		{
			addProfitLine("Profit (session)", plugin.getSession().profit());
		}
		if (config.showRisk())
		{
			String risk = plugin.fmt(plugin.getRiskGp());
			Color riskColor = null;
			if (config.showProtectItem())
			{
				// Protect Item at a glance: neutral outside the Wilderness, green/red inside —
				// where walking in with it off is the mistake this exists to catch.
				final boolean on = plugin.protectItemOn();
				risk += on ? " (On)" : " (Off)";
				if (plugin.inWilderness())
				{
					riskColor = on ? PROTECT_ON_COLOR : PROTECT_OFF_COLOR;
				}
			}
			addLine("Risk", risk, riskColor);
		}
		if (config.showMaxHit())
		{
			final CombatCalc.MaxHitInfo est = plugin.maxHitInfo();
			if (est != null && est.maxHit >= 0)
			{
				addLine(est.specShown() ? "Max hit (spec)" : "Max hit", est.maxHitText(), null);
			}
		}
		if (config.showNetWorth())
		{
			addLine("Net worth", plugin.netWorthDisplay(), null);
		}
		if (config.showBaselineCrates())
		{
			addLine("Crates (baseline)", Long.toString(plugin.getBaseline().crates), null);
		}
		if (config.showSessionCrates())
		{
			addLine("Crates (session)", Long.toString(plugin.getSession().crates), null);
		}
		if (config.showCurrentPoints())
		{
			addLine("Points (current)", plugin.currentBhPointsDisplay(), null);
		}
		if (config.showBaselinePoints())
		{
			addLine("Points (baseline)", Long.toString(plugin.getBaseline().points), null);
		}
		if (config.showSessionPoints())
		{
			addLine("Points (session)", Long.toString(plugin.getSession().points), null);
		}

		return super.render(graphics);
	}

	private void addLine(String left, String right, Color rightColor)
	{
		// Only set the colour when one is given — passing null overrides the builder's white default.
		final LineComponent.LineComponentBuilder b = LineComponent.builder()
			.left(left)
			.right(right);
		if (rightColor != null)
		{
			b.rightColor(rightColor);
		}
		panelComponent.getChildren().add(b.build());
	}

	private void addProfitLine(String left, long profit)
	{
		addLine(left, plugin.fmt(profit), profit >= 0 ? config.profitColor() : config.lossColor());
	}
}
